export function returnTemplateForCategory(category) {
  if (typeof category !== "string") return null;
  const key = category.trim().toLowerCase().replace(/\s+/g, " ");
  return key ? (CATEGORY_RETURN_ALIASES[key] ?? null) : null;
}

/** lib/contact/links.ts telHref: the Call button appears only when this succeeds. */
export function telHref(raw) {
  if (typeof raw !== "string") return null;
  const dialled = raw.trim().replace(/\s*(?:ext\.?|extension|x|#)\s*\d{1,6}\s*$/i, "");
  if (!/^\+?[\d\s().-]+$/.test(dialled)) return null;
  const digits = dialled.replace(/\D/g, "");
  if (digits.length < 7 || digits.length > 15) return null;
  return `tel:${dialled.startsWith("+") ? "+" : ""}${digits}`;
}

/** lib/org/settings.ts and lib/notifications/settings.ts: one address, this pattern, at most 254 characters. */
export function isEmail(raw) {
  return typeof raw === "string" && raw.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(raw.trim());
}

/** lib/public/brand.ts: strict #RRGGBB. */
export function isHexColor(raw) {
  return typeof raw === "string" && /^#[0-9A-Fa-f]{6}$/.test(raw.trim());
}

/** lib/assets/validate.ts year rule: a whole number from 1900 to next year. */
export function yearProblem(raw, now = KIT.fixedDate) {
  const n = Number(String(raw).trim());
  const max = now.getUTCFullYear() + 1;
  return Number.isInteger(n) && n >= 1900 && n <= max ? null : `Year must be a whole number between 1900 and ${max}.`;
}

